head.script:
scwin.onpageload = function() {
    debugger;
    input1.setValue(0);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {};
scwin.trigger2_onclick = function(e) {
    var result = (dataMap1.get("key1") === "")
    debugger;
    //alert( dataMap1.get("key1") );
    //alert( result );
    localStorage.setItem("log", dataMap1.get("key1"));
    localStorage.setItem("log1", result);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 0", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'false'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log");
    localStorage.removeItem("log1");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
